                        >
                          {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
                        </span>
                        <span className="text-sm truncate group-hover:text-primary transition-colors">
                          {item.name}
                        </span>
                        <span className="hidden sm:inline shrink-0 text-xs text-muted-foreground">
                          — {item.showName}
                        </span>
                      </div>
                      {item.notes && (
