                          {item.notes}
                        </p>
                      )}
                    </div>
                    <span className="shrink-0 text-xs font-semibold text-red-400 whitespace-nowrap">
                      {daysLabel(item.daysOverdue)} ago
                    </span>
                  </Link>
                ))}
              </div>
            )}
          </CardContent>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  );
}

