import { useState, useMemo } from "react";
import { Link } from "wouter";
import { ChevronLeft, ChevronRight, CheckCircle2 } from "lucide-react";
import { useGetOverdueItems } from "@workspace/api-client-react";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { formatDate } from "@/lib/date-utils";

const CATEGORY_COLORS: Record<string, string> = {
  "Show Bucket":        "bg-blue-500/15 text-blue-400 border-blue-500/30",
  "Fire Marshal":       "bg-red-500/15 text-red-400 border-red-500/30",
  "ID Sign":            "bg-purple-500/15 text-purple-400 border-purple-500/30",
  "Warehouse Manifest": "bg-cyan-500/15 text-cyan-400 border-cyan-500/30",
  "Vehicle Spotting":   "bg-amber-500/15 text-amber-400 border-amber-500/30",
  eblast:               "bg-pink-500/15 text-pink-400 border-pink-500/30",
};

function chipClass(type: string, category: string | null | undefined) {
  if (type === "eblast") return CATEGORY_COLORS["eblast"];
  return CATEGORY_COLORS[category ?? ""] ?? "bg-slate-500/15 text-slate-400 border-slate-500/30";
}

export function DashboardTaskSlider() {
  const { data: rawItems, isLoading } = useGetOverdueItems();
  const [index, setIndex] = useState(0);

  // Due today first, then overdue oldest→newest (highest daysOverdue first)
  const items = useMemo(() => {
    if (!rawItems) return [];
    const dueToday = rawItems.filter(i => i.daysOverdue === 0);
    const overdue = rawItems
      .filter(i => i.daysOverdue > 0)
      .sort((a, b) => b.daysOverdue - a.daysOverdue);
    return [...dueToday, ...overdue];
  }, [rawItems]);

  if (isLoading) return <Skeleton className="w-full h-32 rounded-lg" />;
  if (items.length === 0) return null;

  const safeIndex = Math.min(index, items.length - 1);
  const item = items[safeIndex];
  const isToday = item.daysOverdue === 0;
  const total = items.length;

  const prev = () => setIndex(i => Math.max(0, i - 1));
  const next = () => setIndex(i => Math.min(total - 1, i + 1));

  const showTab = item.type === "eblast" ? "eblasts" : "tasks";

  return (
    <div className={`rounded-lg border p-5 flex flex-col gap-4 ${isToday ? "bg-amber-500/5 border-amber-500/20" : "bg-red-500/5 border-red-500/20"}`}>
      {/* Header row: label + counter + arrows */}
      <div className="flex items-center justify-between gap-3">
        <span className={`text-xs font-bold uppercase tracking-widest ${isToday ? "text-amber-400" : "text-red-400"}`}>
          {isToday ? "Due Today" : `${item.daysOverdue} ${item.daysOverdue === 1 ? "day" : "days"} overdue`}
        </span>
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground tabular-nums">{safeIndex + 1} / {total}</span>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={prev}
            disabled={safeIndex === 0}
          >
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7"
            onClick={next}
            disabled={safeIndex === total - 1}
          >
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Card body */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex flex-col gap-1.5 min-w-0">
          {/* Chips */}
          <div className="flex items-center gap-1.5 flex-wrap">
            <span className={`text-[10px] font-medium px-1.5 py-0.5 rounded border ${chipClass(item.type, item.category)}`}>
              {item.type === "eblast" ? "E-Blast" : (item.category ?? "Task")}
            </span>
          </div>

          {/* Task name */}
          <p className="text-lg font-semibold leading-tight truncate">{item.name}</p>

          {/* Show + due date */}
          <p className="text-sm text-muted-foreground">
            {item.showName}
            <span className="mx-1.5 opacity-40">•</span>
            Due {formatDate(item.dueDate)}
          </p>

          {/* Notes */}
          {item.notes && (
            <p className="text-xs text-muted-foreground italic truncate">{item.notes}</p>
          )}
        </div>

        <Link
          href={`/shows/${item.showId}?tab=${showTab}`}
          className="shrink-0"
        >
          <Button variant="outline" size="sm" className="gap-1.5">
            <CheckCircle2 className="h-3.5 w-3.5" />
            Open
          </Button>
        </Link>
      </div>

      {/* Dot indicators (up to 10 shown) */}
      {total > 1 && total <= 10 && (
        <div className="flex items-center gap-1 justify-center">
          {items.map((_, i) => (
            <button
              key={i}
              onClick={() => setIndex(i)}
              className={`rounded-full transition-all ${
                i === safeIndex
                  ? `h-1.5 w-4 ${isToday ? "bg-amber-400" : "bg-red-400"}`
                  : "h-1.5 w-1.5 bg-muted-foreground/30 hover:bg-muted-foreground/50"
              }`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

